import React, { useEffect, useRef, useState } from "react";

const RemoteViewer = ({ hostname }) => {
  const canvasRef = useRef(null);
  const [status, setStatus] = useState("Desconectado");
  const wsRef = useRef(null);

  const SERVER_IP = "172.21.20.14";

  useEffect(() => {
    if (!hostname) return;

    const wsUrl = `ws://${SERVER_IP}:8006/api/ws/operator/${hostname}`;
    setStatus("Conectando...");
    const ws = new WebSocket(wsUrl);
    wsRef.current = ws;

    ws.onopen = () => {
      setStatus("Conectado");
      console.log("Conectado al feed de escritorio remoto");
    };

    ws.onmessage = (event) => {
      const base64Image = event.data;
      // Solo dibujar si parece imagen (base64 largo)
      if (!base64Image || base64Image.length < 100) return;

      const img = new Image();
      img.src = `data:image/jpeg;base64,${base64Image}`;
      img.onload = () => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext("2d");
        if (canvas.width !== img.width || canvas.height !== img.height) {
          canvas.width = img.width;
          canvas.height = img.height;
        }
        ctx.drawImage(img, 0, 0);
      };
    };

    ws.onerror = () => setStatus("Error de conexion");
    ws.onclose = () => setStatus("Desconectado");

    return () => {
      if (ws) ws.close();
    };
  }, [hostname]);

  const send = (obj) => {
    const ws = wsRef.current;
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.send(JSON.stringify(obj));
    }
  };

  const getNormPos = (e) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;
    return {
      x: Math.min(1, Math.max(0, x)),
      y: Math.min(1, Math.max(0, y)),
    };
  };

  const onMouseMove = (e) => {
    const { x, y } = getNormPos(e);
    send({ type: "mouse", action: "move", x, y });
  };

  const onMouseDown = (e) => {
    e.preventDefault();
    const { x, y } = getNormPos(e);
    send({ type: "mouse", action: "down", x, y, button: e.button });
    canvasRef.current?.focus();
  };

  const onMouseUp = (e) => {
    e.preventDefault();
    const { x, y } = getNormPos(e);
    send({ type: "mouse", action: "up", x, y, button: e.button });
  };

  const onDoubleClick = (e) => {
    e.preventDefault();
    const { x, y } = getNormPos(e);
    send({ type: "mouse", action: "dblclick", x, y, button: e.button });
  };

  const onWheel = (e) => {
    e.preventDefault();
    const { x, y } = getNormPos(e);
    const dy = e.deltaY > 0 ? -1 : 1;
    send({ type: "mouse", action: "scroll", x, y, dy });
  };

  const onKeyDown = (e) => {
    e.preventDefault();
    send({ type: "key", action: "down", key: e.key });
  };

  const onKeyUp = (e) => {
    e.preventDefault();
    send({ type: "key", action: "up", key: e.key });
  };

  return (
    <div
      style={{
        textAlign: "center",
        backgroundColor: "#1e1e1e",
        padding: "15px",
        borderRadius: "8px",
      }}
    >
      <div style={{ marginBottom: "10px", color: "#fff", fontWeight: "bold" }}>
        Control Remoto:{" "}
        <span style={{ color: "#00bcd4" }}>{hostname}</span> | Estado: {status}
      </div>
      <div
        style={{
          display: "inline-block",
          border: "2px solid #333",
          overflow: "hidden",
          borderRadius: "4px",
        }}
      >
        <canvas
          ref={canvasRef}
          tabIndex={0}
          onMouseMove={onMouseMove}
          onMouseDown={onMouseDown}
          onMouseUp={onMouseUp}
          onDoubleClick={onDoubleClick}
          onWheel={onWheel}
          onKeyDown={onKeyDown}
          onKeyUp={onKeyUp}
          onContextMenu={(e) => e.preventDefault()}
          style={{
            cursor: "crosshair",
            maxWidth: "100%",
            height: "auto",
            display: "block",
            outline: "none",
          }}
        />
      </div>
      <p style={{ color: "#888", fontSize: "12px", marginTop: "8px" }}>
        Haz clic en la imagen para enfocar teclado. Clic derecho e izquierdo activos.
      </p>
    </div>
  );
};

export default RemoteViewer;
